"""Linguistic presentation of measured results; no new empirical claims."""
def revise(blocks,m,key):
    abstract=(f'Промежуточное решение модели может состоять из неполных английских предложений, формул, стрелок и коротких ссылок. Цель — описать сохраняемые языковые связи и границы восстановления из контекста. Сопоставлены {m["rows"]} цепочек четырёх моделей по {m["questions"]} общим вопросам; окна фиксированной длины связаны с разбором 96 отобранных и 32 случайных фрагментов по восьми категориям. Сравнение полных цепочек смешивает длину и регулярность записи: после контроля длины порядок Claude и DeepSeek по отношению размеров zlib/UTF-8 меняется. В примерах маркеры вывода, отрицание и модальность могут сохраняться при пропусках связок, субъектов и аргументов. Фрагменты Mythos и Astra показывают зависимость интерпретации от задачи. Схема позволяет отделять выраженную связь и грамматическое дополнение от содержательной проверки перехода.')
    abstract_en=(f'Intermediate model solutions may consist of incomplete English sentences, formulas, arrows and brief references. This study describes retained linguistic relations and the limits of contextual reconstruction. We compare {m["rows"]:,} traces from four models answering {m["questions"]:,} shared questions, linking fixed-length windows to eight-category analysis of 96 selected and 32 random excerpts. Whole-trace comparisons mix length with textual regularity: controlling length reverses the ordering of Claude and DeepSeek by the zlib-to-UTF-8 size ratio. In the examples, inference markers, negation and modality may survive omissions of copulas, subjects and arguments. Published Mythos and Astra excerpts illustrate dependence on task context. The scheme distinguishes explicit relations and grammatical completion from substantive verification of a reasoning step.')
    blocks['Введение']=[
    'Промежуточное решение модели может содержать короткие предикативные блоки, формулы и знаки вместо полных английских предложений. В опубликованной карточке Mythos [1] такая запись использует словоформы и локальную нотацию, значения которой зависят от задачи. Для лингвиста существенны сохраняемые отношения: что обозначают связка, отрицание, маркер вывода и ссылка, когда часть конструкции опущена? Текстовая цепочка даёт материал для этого разбора, хотя не открывает всех внутренних вычислений модели.',
    'Исследования наблюдаемости [2, 12], причинной роли записи [3–5] и формальной проверки [6] требуют различать текст, вычисление и правильность перехода. Поэтому восстановление английской грамматики само по себе не восстанавливает доказательство.',
    'Иерархические описания переходов [7], смена языка рассуждения [8], объединение записи в укрупнённые единицы [9], черновая запись [10] и обучение по сокращённым цепочкам [11] рассматривают разные способы организации текста. Однако эти подходы не дают готовой разметки локальных пропусков английской конструкции в выбранном корпусе. Здесь требуется связать измеряемую длину и сжимаемость с конкретными языковыми средствами и доступным контекстом.',
    'Цель — описать средства сокращения и выявить сохраняемые связи в отобранных фрагментах. Сравниваются четыре модели на одинаковых вопросах; Mythos и Astra [1, 13, 14] служат внешними иллюстрациями с указанными условиями получения.',
    'Научная новизна. Совместный корпусный и лингвистический разбор разграничивает краткость, алгоритмическую сжимаемость и языковое сокращение. Схема восьми категорий связывает числовые признаки с локальными конструкциями и отделяет грамматическое дополнение от содержательного восстановления из задачи.',
    'Практическая значимость. Схема помогает различать выраженные в цепочке элементы и отношения, достроенные исследователем из контекста. Это полезно для корпусной разметки, сопоставления моделей и проверки интерпретаций сокращённой языково-символической записи.'
    ]
    methods=blocks['Материалы и методы']
    methods[0]=f'Использован открытый корпус Measuring Chain-of-Thought Monitorability Transcripts [12], версия a7a8b25ae467. Из 446 208 исходных строк выделены непустые цепочки базового режима; окончательный ответ не подменяет промежуточную запись. Сопоставлены все {m["questions"]} общих вопроса из {m["tasks"]} задач BBH, MMLU и GPQA: по одной цепочке Claude 3.7 Sonnet, DeepSeek R1 0528, Qwen3 235B A22B thinking 2507 и QwQ 32B. Mythos и Astra в количественный корпус не входят.'
    methods[1]=methods[1].replace('числом whitespace-токенов','числом единиц, разделённых пробельными символами (далее — токенов)').replace('zlib level 9','zlib на уровне 9').replace('128 whitespace-токенов','128 токенов')
    methods[2]=methods[2].replace('плотность emoji','плотность эмодзи')
    methods[3]='Лексическая редкость L — доля английских слов с частотностью по шкале Ципфа ниже 2 в библиотеке wordfreq. Выделяются последовательности латинских букв с одним внутренним апострофом; регистр понижается, дефис разделяет слова. Имена не исключаются; редкость сама по себе не означает новое слово. Повторяемость Q = 1−U/G рассчитана для перекрывающихся четырёхграмм исходных токенов: U — число уникальных, G — всех; регистр и пунктуация сохранены.'
    methods[4]='Для восьми основных показателей рассчитаны все шесть пар моделей: медианы парных разностей, величины рангового эффекта и 95% доверительные интервалы. Иерархическая повторная выборка включает 1000 повторений: сначала выбираются задачи, затем вопросы внутри каждой выбранной задачи; пары моделей сохраняются. Начальное значение генератора случайных чисел — 20261002. Вопросные тесты Уилкоксона с поправкой Холма доступны в дополнительных таблицах, но не учитывают зависимость внутри задачи; основной вывод опирается на иерархические интервалы. Проверки устойчивости используют окна 64, 256 и 512 токенов, только начальные окна, 800 символов Unicode и 800 байтов UTF-8. Для последних двух размеров рассчитывается только отношение сжатия R; байтовые срезы не декодируются для языкового разбора. Отбор цепочек с не менее 95% латинских букв сохранил всю основную выборку и не проверяет отдельно английский язык.'
    methods[5]='Для разбора выбраны 24 вопроса: по 8 с наибольшими S и P и 8 случайных. Поиск ведётся по максимальному показателю четырёх моделей; группы не пересекаются. Из наиболее символьно насыщенного окна каждой цепочки взяты 40 токенов: 96 фрагментов с вопросом и контекстом. Справочник включает эллипсис, символическую замену, окказиональное словообразование, пропуск аргумента, маркер вывода, переключение языка, телеграфный синтаксис и сокращённую ссылку. Обрезка фрагмента не считается эллипсисом. Первичная машинная разметка выполнена по справочнику: решения и текстовые основания сформулированы языковой моделью. Независимая проверка человеком ещё не проведена; согласие не оценивалось. Для контроля отбора по знакам равновероятно выбраны ещё 8 вопросов из всех 3022 и случайная позиция до 40 токенов каждой цепочки: 32 фрагмента, начальное значение генератора 20261003. Разметки хранятся отдельно; эти частоты не оценивают распространённость в корпусе.'
    methods[6]='Программный анализатор на Python и Streamlit связывает вопрос, исходную цепочку, локальные показатели и основания разметки. Он использован для парного отбора, извлечения фрагментов, расчёта признаков и интервалов. Исходный контекст позволяет проверить языковую конструкцию и подготовить независимую разметку. Код, конфигурация, зависимости и таблицы подготовлены для репозитория github.com/ANSTAPABAL/research-mythos. Версия публикации и состояние выгрузки фиксируются в материалах проекта.'
    blocks['Обсуждение']=[
    'В отобранных примерах сокращённая запись сохраняет часть английских языковых связей. Маркер вывода указывает на переход от основания к результату, отрицание и модальный глагол ограничивают утверждение, а морфология помогает распознать функцию словоформы. При этом субъект, связка или аргумент могут оставаться невыраженными. Формула задаёт отношение величин, но для чтения ссылки или проверки перехода может понадобиться контекст задачи.',
    'Схема категорий позволяет отделить грамматическое дополнение от содержательного восстановления. Добавление связки в «Not integer» раскрывает предикативную конструкцию. Добавление условия b≠c к объяснению Astra восстанавливает математическую посылку и требует обращения к задаче. Это различие полезно для корпусной разметки: исследователь должен отмечать, что выражено в тексте, и отдельно — что он достроил из контекста. Локальные показатели в программном анализаторе помогают находить и проверять такие случаи, сохраняя исходную запись.',
    'Смена порядка Claude и DeepSeek показывает значение единицы сравнения. Полные цепочки различаются по длине и регулярности записи; фиксированные окна контролируют длину. Проверки на токенах, символах и байтах сохраняют направление различий Claude. Такой контроль нужен, прежде чем связывать сжимаемость с языковой формой.',
    'Ограничения связаны с машинной разметкой без независимой проверки человеком и отбором 96 фрагментов по знакам. Контрольные 32 фрагмента недостаточны для оценки корпусной распространённости. Состав выборок разной длины меняется; интервалы отражают задачи этого корпуса. Причинная связь сжимаемости с языковыми категориями и польза сокращений для качества решения не проверялись.'
    ]
    blocks['Заключение']=[
    'Предложена схема восьми категорий, связанная через программный анализатор с исходным текстом. В отобранных фрагментах языковые маркеры сохраняются при пропусках связок и аргументов. Разграничены краткость, алгоритмическая сжимаемость и языковое сокращение, а в разборе пропусков — грамматическое дополнение и восстановление условий задачи. Смена порядка Claude и DeepSeek показывает необходимость контроля длины при сравнении сжимаемости. Схема помогает размечать подобные тексты и проверять их интерпретации, отделяя выраженную связь от добавленных условий.'
    ]
    for section,texts in blocks.items():
        blocks[section]=[t.replace('whitespace-токенов','токенов').replace('иерархического bootstrap','иерархической повторной выборки').replace('bootstrap','повторная выборка').replace('ИИ-разметка','машинная разметка').replace('raw CoT','исходной текстовой цепочки').replace('trace(H²)','следа матрицы H²').replace('необычное словообразование','окказиональное словообразование').replace('смена естественного языка не были','переключение естественного языка не были') for t in texts]
    blocks['Материалы и методы'][3]=blocks['Материалы и методы'][3].replace('доля английских слов','доля выделенных латинских слов').replace('в библиотеке wordfreq','в английском словаре wordfreq')
    blocks['Материалы и методы'][5]=blocks['Материалы и методы'][5].replace('по 8 с наибольшими S и P и 8 случайных','8 с наибольшим S, 8 с наибольшим P среди остальных и 8 случайных')
    blocks['Результаты'][2]=blocks['Результаты'][2].replace('Необычное словообразование','Окказиональное словообразование')
    blocks['Материалы и методы'][5]=blocks['Материалы и методы'][5].replace('выполнена по справочнику:','выполнена по формализованному справочнику категорий:')
    blocks['Результаты'][2]=blocks['Результаты'][2].replace('Малый объём и машинная разметка не позволяют оценивать распространённость.','Малый объём контрольной выборки не позволяет оценивать распространённость явлений в корпусе.')
    blocks['Результаты'][0]='Контроль длины меняет порядок Claude и DeepSeek по сжимаемости записи; сравнение полных цепочек смешивает длину и регулярность текста. '+blocks['Результаты'][0].replace('Это различие регулярности записи, а не измерение её смыслового сокращения.','')
    return abstract,abstract_en,blocks
